pub const SCRIPT_HEAD: &str = "$ErrorActionPreference='Stop'; ";
pub const SCRIPT_REST: &str = "$actor=[System.Security.Principal.WindowsIdentity]::GetCurrent().User; $sections=[System.Security.AccessControl.AccessControlSections]::Owner -bor [System.Security.AccessControl.AccessControlSections]::Access; $takeRights=[System.Security.AccessControl.RegistryRights]::TakeOwnership -bor [System.Security.AccessControl.RegistryRights]::ReadPermissions; $aclRights=[System.Security.AccessControl.RegistryRights]::TakeOwnership -bor [System.Security.AccessControl.RegistryRights]::ReadPermissions -bor [System.Security.AccessControl.RegistryRights]::ChangePermissions; $writeRights=[System.Security.AccessControl.RegistryRights]::SetValue -bor [System.Security.AccessControl.RegistryRights]::QueryValues; $failures=New-Object 'System.Collections.Generic.List[string]'; function Set-CacheValues($key) { if ($disable) { $key.SetValue('UserWriteCacheSetting',1,[Microsoft.Win32.RegistryValueKind]::DWord); $key.SetValue('CacheIsPowerProtected',1,[Microsoft.Win32.RegistryValueKind]::DWord); if (($key.GetValue('UserWriteCacheSetting',$null) -ne 1) -or ($key.GetValue('CacheIsPowerProtected',$null) -ne 1)) { throw 'The disabled values did not verify.' } } else { $key.DeleteValue('UserWriteCacheSetting',$false); $key.DeleteValue('CacheIsPowerProtected',$false); if (($null -ne $key.GetValue('UserWriteCacheSetting',$null)) -or ($null -ne $key.GetValue('CacheIsPowerProtected',$null))) { throw 'The Windows-default values did not verify.' } } } foreach ($id in $ids) { $dpRel = 'SYSTEM\\CurrentControlSet\\Enum\\' + $id + '\\Device Parameters\\Disk'; $originalAcl=$null; $aclChanged=$false; $takeKey=$null; $aclKey=$null; $writeKey=$null; $restoreKey=$null; try { $probe=[Microsoft.Win32.Registry]::LocalMachine.OpenSubKey($dpRel); if ($null -eq $probe) { $writeKey=[Microsoft.Win32.Registry]::LocalMachine.CreateSubKey($dpRel,[Microsoft.Win32.RegistryKeyPermissionCheck]::ReadWriteSubTree); if ($null -eq $writeKey) { throw 'The disk parameter key could not be created.' } Set-CacheValues $writeKey; } else { $probe.Close(); $takeKey=[Microsoft.Win32.Registry]::LocalMachine.OpenSubKey($dpRel,[Microsoft.Win32.RegistryKeyPermissionCheck]::ReadWriteSubTree,$takeRights); if ($null -eq $takeKey) { throw 'The disk parameter ACL could not be opened.' } $originalAcl=$takeKey.GetAccessControl($sections); $ownerAcl=$takeKey.GetAccessControl([System.Security.AccessControl.AccessControlSections]::Owner); $ownerAcl.SetOwner($actor); $takeKey.SetAccessControl($ownerAcl); $aclChanged=$true; $takeKey.Close(); $takeKey=$null; $aclKey=[Microsoft.Win32.Registry]::LocalMachine.OpenSubKey($dpRel,[Microsoft.Win32.RegistryKeyPermissionCheck]::ReadWriteSubTree,$aclRights); if ($null -eq $aclKey) { throw 'The disk parameter ACL could not be changed.' } $temporaryAcl=$aclKey.GetAccessControl($sections); $rule=New-Object System.Security.AccessControl.RegistryAccessRule($actor,[System.Security.AccessControl.RegistryRights]::FullControl,[System.Security.AccessControl.InheritanceFlags]::None,[System.Security.AccessControl.PropagationFlags]::None,[System.Security.AccessControl.AccessControlType]::Allow); $temporaryAcl.AddAccessRule($rule); $aclKey.SetAccessControl($temporaryAcl); $aclKey.Close(); $aclKey=$null; $writeKey=[Microsoft.Win32.Registry]::LocalMachine.OpenSubKey($dpRel,[Microsoft.Win32.RegistryKeyPermissionCheck]::ReadWriteSubTree,$writeRights); if ($null -eq $writeKey) { throw 'The disk parameter key could not be opened for writing.' } Set-CacheValues $writeKey; } } catch { $failures.Add(($id + ': ' + $_.Exception.Message)) | Out-Null; } finally { if ($null -ne $writeKey) { $writeKey.Close() } if ($null -ne $takeKey) { $takeKey.Close() } if ($null -ne $aclKey) { $aclKey.Close() } if ($aclChanged -and $null -ne $originalAcl) { try { $restoreKey=[Microsoft.Win32.Registry]::LocalMachine.OpenSubKey($dpRel,[Microsoft.Win32.RegistryKeyPermissionCheck]::ReadWriteSubTree,$aclRights); if ($null -eq $restoreKey) { throw 'The original ACL could not be reopened.' } $restoreKey.SetAccessControl($originalAcl); } catch { $failures.Add(($id + ': ACL restore failed: ' + $_.Exception.Message)) | Out-Null; } finally { if ($null -ne $restoreKey) { $restoreKey.Close() } } } } } if ($failures.Count -gt 0) { [Console]::Error.WriteLine(($failures -join [Environment]::NewLine)); exit 1 }";
